def is_possible(a, b, c, d):
    total = a + b + c + d
    if total % 2 != 0:
        return False
    if abs(a - b) > 1 or abs(b - c) > 1 or abs(c - d) > 1 or abs(d - a) > 1:
        return False
    return True

def construct_sequence(a, b, c, d):
    total = a + b + c + d
    half = total // 2
    seq = []

    if a >= b:
        seq.extend([0] * a)
        seq.extend([1] * b)
        a -= b
    else:
        seq.extend([1] * b)
        seq.extend([0] * a)
        b -= a

    if c >= d:
        seq.extend([2] * c)
        seq.extend([3] * d)
        c -= d
    else:
        seq.extend([3] * d)
        seq.extend([2] * c)
        d -= c

    if a > 0:
        seq.insert(half, 0)
        a -= 1
    if b > 0:
        seq.insert(half, 1)
        b -= 1
    if c > 0:
        seq.insert(half, 2)
        c -= 1
    if d > 0:
        seq.insert(half, 3)
        d -= 1

    return seq

a, b, c, d = map(int, input().split())
if is_possible(a, b, c, d):
    print("YES")
    print(*construct_sequence(a, b, c, d))
else:
    print("NO")
